package dev.by1337.virtualentity.api.tracker; import java.util.*;import dev.by1337.virtualentity.api.virtual.VirtualEntity;import org.bukkit.World;import org.by1337.blib.geom.Vec3d; public class PlayerTracker {public static final List<PlayerTracker> created=new ArrayList<>();public int ticks,removed;public final List<VirtualEntity> entities;public PlayerTracker(World w,List<VirtualEntity> e,Vec3d pos,int radius){if(radius!=64)throw new AssertionError();entities=e;created.add(this);}public void tick(){ticks++;}public void removeAll(){removed++;}}
